// Categoría que sincroniza este workflow (ID de liga de FotMob).
// Para una temporada nueva, cambiar acá el season.
const leagueId = 9305;
const season = '2026';

// FotMob junta B Metro y Federal A en la misma liga (9213): se separan
// por las tablas en las que están los equipos de cada partido.
const tableFilter = null;

// Tope de partidos a bajar por corrida, para no pedirle demasiado a
// FotMob de una vez. Lo que quede pendiente sigue en la próxima.
const maxPerRun = 150;

return [{
  json: {
    category: "Copa Argentina",
    leagueId,
    season,
    tableFilter,
    includeTablePrefix: tableFilter ? tableFilter.include : '',
    excludeTablePrefix: tableFilter ? tableFilter.exclude : '',
    maxPerRun
  }
}];

const raw = $('Fetch Season Fixtures').first().json.stdout;

if (!raw) {
  throw new Error('Python scraper returned empty stdout');
}

let payload;

try {
  payload = JSON.parse(raw);
} catch (error) {
  throw new Error(
    `Could not parse scraper output as JSON: ${error.message}`
  );
}

if (!Array.isArray(payload.matches)) {
  throw new Error(
    'Scraper output does not contain a matches array'
  );
}

const { tableFilter } = $('Category Config').first().json;

// Se queda con los partidos de esta categoría según las tablas de sus equipos
const belongs = match => {
  if (!tableFilter) return true;

  const tables = match.tables || [];

  if (tableFilter.include) {
    return tables.some(table => table.startsWith(tableFilter.include));
  }

  return !tables.some(table => table.startsWith(tableFilter.exclude));
};

return payload.matches.filter(belongs).map(match => ({
  json: {
    source: payload.source,

    leagueId: match.leagueId,
    season: match.season,

    matchId: match.matchId,
    utcTime: match.utcTime,
    finished: match.finished,
    started: match.started,
    cancelled: match.cancelled,

    round: match.round,
    pageUrl: match.pageUrl,

    home: match.home,
    away: match.away
  }
}));

const items = $input.all();

return items.filter(item => {
  const match = item.json;

  return (
    match.finished === true &&
    match.cancelled !== true
  );
});

const { maxPerRun } = $('Category Config').first().json;

// Datos del fixture para ordenar y contar por liga
const fixture = new Map(
  $('Only finished games').all().map(item => [String(item.json.matchId), item.json])
);

// Primero los que no tienen resultado en la base y, dentro de cada grupo, los
// más recientes. En el ascenso FotMob no publica jugadores: esos partidos
// quedan siempre "incompletos" y, sin este orden, ocupaban el tope de cada
// corrida y los resultados nuevos quedaban atrás.
const sinResultado = new Set(
  $input.all().filter(item => item.json.sinResultado).map(item => String(item.json.matchId))
);

const pending = $input.all()
  .map(item => fixture.get(String(item.json.matchId)))
  .filter(Boolean)
  .sort((a, b) =>
    (sinResultado.has(String(b.matchId)) - sinResultado.has(String(a.matchId))) ||
    String(b.utcTime).localeCompare(String(a.utcTime))
  );

const selected = pending.slice(0, maxPerRun);
const ids = selected.map(match => String(match.matchId));

return [{
  json: {
    pendingTotal: pending.length,
    withoutResult: sinResultado.size,
    count: ids.length,
    matchIds: ids,
    matchIdsCsv: ids.join(',')
  }
}];

const raw = $json.stdout;

if (!raw) {
  throw new Error('fotmob_sync.py download returned empty stdout');
}

let payload;

try {
  payload = JSON.parse(raw);
} catch (error) {
  throw new Error(
    `Could not parse download output as JSON: ${error.message}`
  );
}

// Se cargan los recién bajados y los que ya estaban guardados
const toLoad = [...payload.downloaded, ...payload.cached];

return [{
  json: {
    ...payload,
    toLoad,
    toLoadCsv: toLoad.join(',')
  }
}];

const raw = $json.stdout;

if (!raw) {
  throw new Error('load_matches.py returned empty stdout');
}

let load;

try {
  load = JSON.parse(raw);
} catch (error) {
  throw new Error(
    `Could not parse load output as JSON: ${error.message}`
  );
}

const collect = $('Collect Match IDs').first().json;
const config = $('Category Config').first().json;

// Las posiciones no cortan el workflow si fallan: se informa acá
let standings;
try {
  standings = JSON.parse($('Load Standings').first().json.stdout);
} catch (error) {
  standings = { error: $('Load Standings').first().json.stderr || 'no output' };
}
const download = $('Parse Download').first().json;

const failed = [...download.failed, ...load.failed];

return [{
  json: {
    category: config.category,
    standingsRows: standings.rows ?? null,
    standings,
    pendingTotal: collect.pendingTotal,
    requested: collect.count,
    downloadedCount: download.downloaded.length,
    cachedCount: download.cached.length,
    syncedCount: load.synced.length,
    replacedCount: (load.replaced || []).length,
    replaced: load.replaced || [],
    failedCount: failed.length,
    failed,
    synced: load.synced,
    finishedAt: new Date().toISOString()
  }
}];
